use kino_core::{commands::{Session,dispatch},render};use serde_json::json;
#[test]fn decode_window_order_does_not_shift_frames(){let path=std::env::temp_dir().join(format!("kino-phase-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","testsrc2=size=128x72:rate=30:duration=2.2","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());for managed in [false,true]{for speed in [1.,0.7,1.2]{let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":64,"height":36,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"in_point":0.13,"speed":speed,"duration":1.56})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":managed,"linear_resample":managed,"input_transfer":8,"working_gamut":3}})).unwrap();let mut cold=render::Cache::new();render::prepare_at(&s.project,&mut cold,Some(0.76)).unwrap();let a=render::render_frame(&s.project,0.76,&cold).unwrap();let mut sequential=render::Cache::new();for t in [0.24,0.52,0.76]{render::prepare_at(&s.project,&mut sequential,Some(t)).unwrap();}let b=render::render_frame(&s.project,0.76,&sequential).unwrap();assert_eq!(a.d,b.d,"managed{managed} speed{speed}");let mut full=render::Cache::new();render::prepare(&s.project,&mut full).unwrap();let b=render::render_frame(&s.project,0.76,&full).unwrap();assert_eq!(a.d,b.d,"full managed{managed} speed{speed}");}}std::fs::remove_file(path).unwrap();}

#[test]fn fractional_and_variable_rate_windows_stay_identical(){for (name,filter) in [("fractional","fps=30000/1001"),("variable","select='not(mod(n,3))',setpts=PTS")]{let path=std::env::temp_dir().join(format!("kino-phase-{name}-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","testsrc2=size=128x72:rate=30:duration=2.2","-vf",filter,"-vsync","vfr","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":64,"height":36,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"in_point":0.13,"duration":1.56})).unwrap();let mut full=render::Cache::new();render::prepare(&s.project,&mut full).unwrap();for t in [0.12,0.52,0.76,1.24]{let expected=render::render_frame(&s.project,t,&full).unwrap();let mut cold=render::Cache::new();render::prepare_at(&s.project,&mut cold,Some(t)).unwrap();assert_eq!(expected.d,render::render_frame(&s.project,t,&cold).unwrap().d,"{name} t{t}");}std::fs::remove_file(path).unwrap();}}
